// Clean each job: strip HTML from the description and keep only the fields we need
return $input.all().map(item => {
  const j = item.json;
  const text = (j.description || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 3000); // keep the prompt short to save tokens
  return {
    json: {
      title: j.title,
      company: j.company_name,
      location: j.candidate_required_location,
      url: j.url,
      description: text
    }
  };
});

