// Merge the AI analysis back with the original job info
const jobs = $('Clean Description').all();
return $input.all().map((item, i) => {
  let ai = {};
  try {
    ai = JSON.parse(item.json.choices[0].message.content);
  } catch (e) {
    ai = { summary: 'Could not parse AI response', top_skills: [] };
  }
  const job = jobs[i].json;
  return {
    json: {
      title: job.title,
      company: job.company,
      location: job.location,
      seniority: ai.seniority,
      student_fit_score: ai.student_fit_score,
      top_skills: (ai.top_skills || []).join(', '),
      summary: ai.summary,
      reason: ai.reason,
      url: job.url
    }
  };
}).sort((a, b) => (b.json.student_fit_score || 0) - (a.json.student_fit_score || 0));
